    radial-gradient(circle at top left, rgba(96, 165, 250, 0.18), transparent 30rem),
    radial-gradient(circle at top right, rgba(34, 197, 94, 0.10), transparent 28rem),
    var(--bg);
  color: var(--text);
  font-family:
    Inter,
