tbody tr:last-child td {
  border-bottom: none;
}

tr:hover td {
  background: rgba(96, 165, 250, 0.06);
}

.mono,
.code {
  font-family:
    ui-monospace,
    SFMono-Regular,
    Menlo,
    Monaco,
    Consolas,
    monospace;
}

.muted {
  color: var(--muted);
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  border-radius: 999px;
  padding: 0.2rem 0.6rem;
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.03em;
  color: #020617;
  white-space: nowrap;
}

.badge-pass {
  background: var(--pass);
}

.badge-fail {
  background: var(--fail);
  color: white;
}

.badge-diff {
  background: var(--diff);
  color: white;
}

.badge-timeout {
  background: var(--timeout);
}

.badge-skip {
  background: var(--skip);
  color: white;
}

.badge-cancel {
  background: var(--cancel);
  color: white;
}

.badge-invalid {
  background: var(--invalid);
  color: white;
}

.badge-none {
  background: var(--none);
}

.badge-link {
  text-decoration: none;
  display: inline-flex;
}

.badge-link:hover {
  text-decoration: none;
  filter: brightness(1.08);
}

.back-button {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin-bottom: 1rem;
  padding: 0.45rem 0.75rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
  font-weight: 700;
}

.back-button:hover {
  text-decoration: none;
  border-color: rgba(96, 165, 250, 0.65);
  background: rgba(96, 165, 250, 0.10);
}

pre {
  margin: 0;
  padding: 1.25rem;
  overflow-x: auto;
  color: #d1d5db;
  background: #020617;
  border-radius: 14px;
  border: 1px solid var(--border);
}

.output {
  margin-top: 1.5rem;
}

.meta-grid {
  display: grid;
  grid-template-columns: minmax(180px, 260px) 1fr;
}

.meta-grid > div {
  padding: 0.8rem 1rem;
  border-bottom: 1px solid rgba(55, 65, 81, 0.75);
}

.meta-grid > div:nth-last-child(-n + 2) {
  border-bottom: none;
}

.meta-key {
  color: var(--muted);
  font-weight: 700;
}

.measurement-value {
  white-space: pre-wrap;
}

.footer {
  margin-top: 2rem;
  color: var(--muted);
  font-size: 0.85rem;
}

@media (max-width: 720px) {
  main {
    padding: 1rem;
  }

  h1 {
    font-size: 1.9rem;
  }

  .meta-grid {
    grid-template-columns: 1fr;
  }

  .meta-grid > div:nth-last-child(-n + 2) {
    border-bottom: 1px solid rgba(55, 65, 81, 0.75);
  }
}

.cards.cards-compact {
  grid-template-columns: repeat(8, minmax(0, 1fr));
  gap: 0.65rem;
}

@media (max-width: 900px) {
  .cards.cards-compact {
    grid-template-columns: repeat(auto-fit, minmax(105px, 1fr));
  }
}

.cards-compact .card {
  padding: 0.7rem 0.8rem;
  border-radius: 12px;
}

.cards-compact .card-label {
  font-size: 0.68rem;
  letter-spacing: 0.06em;
}

.cards-compact .card-value {
  margin-top: 0.2rem;
  font-size: 1.35rem;
}


th.sortable {
  cursor: pointer;
  user-select: none;
}

th.sortable:hover {
  color: var(--text);
}

th.sortable::after {
  content: " ⇅";
  color: var(--muted);
  font-size: 0.75em;
}

th.sortable.sort-asc::after {
  content: " ↑";
  color: var(--link);
}

th.sortable.sort-desc::after {
  content: " ↓";
  color: var(--link);
}

